// <auto-generated />
using System.Collections.Generic;
using Fanex.Excel.Enums;
using Fanex.Excel.Models;
using RiskControl.NonSportsGamesStatistics.Common;
using RiskControl.NonSportsGamesStatistics.Model;
using RiskControl.NonSportsGamesStatistics.TopTwenty.Common;

namespace RiskControl.NonSportsGamesStatistics.TopTwenty.GroupStatistics
{
    public class GridOptionBuilderServiceImp<TQuery> : GridOptionBuilderService<UserNameViewGroupStatisticsWithTotalModel, TQuery>
        where TQuery: BaseStatisticQueryModel
    {
        private const int NoOfPlayersColumnIndex = 1;
        private readonly GridOptionDataRowBuilderService gridDataRowBuilderService;
        private readonly GridOptionRemoveColumnService gridOptionRemoveColumnService;
        private readonly GridOptionHeaderBuilderService headerBuilderService;

        public GridOptionBuilderServiceImp(
            GridOptionDataRowBuilderService gridDataRowBuilderService,
            GridOptionHeaderBuilderService headerBuilderService,
            GridOptionRemoveColumnService gridOptionRemoveColumnService)
        {
            this.gridDataRowBuilderService = gridDataRowBuilderService;
            this.headerBuilderService = headerBuilderService;
            this.gridOptionRemoveColumnService = gridOptionRemoveColumnService;
        }

        public GridOptions BuildGridOptions(UserNameViewGroupStatisticsWithTotalModel statistics,
            TQuery queryModel)
        {
            var gridOptions = new GridOptions
            {
                ShowTitle = true,
                TitleType = TitleType.TwoLineBlue,
                TitleInfoText = queryModel.Title,
                BodyRows = BuildBodyRows(statistics.Statistics, queryModel.ViewByInteger),
                Columns = BuildHeaderColumns(queryModel),
                FooterRows = BuildFooter(statistics.Total, queryModel.ViewByInteger),
                ShowFooter = true,
                ShowHighlightRow = false,
                ShowDistinctRow = false,
                ShowTree = true
            };

            gridOptions = gridOptionRemoveColumnService.RemoveColumn(gridOptions, queryModel.RemovalColumns);

            return gridOptions;
        }

        private List<HeaderColumns> BuildHeaderColumns(BaseStatisticQueryModel queryModel)
        {
            var headerColumns = headerBuilderService.BuildBaseHeaderColumns(queryModel);

            headerColumns?.Insert(NoOfPlayersColumnIndex,
                new HeaderColumns
                {
                    Name = "NoOfPlayers",
                    HeaderText = "No. Players",
                    Width = 100,
                    Sort = true,
                    SortDirection =
                        queryModel.SortColumnName == "NoOfPlayers" ? queryModel.SortDirection : string.Empty
                });

            return headerColumns;
        }

        private List<GridDataRow> BuildBodyRows(List<UserNameViewGroupStatisticsModel> statistics, bool viewByInteger)
        {
            var dataRows = new List<GridDataRow>();
            foreach (var group in statistics)
            {
                var groupDataRows = gridDataRowBuilderService.BuildGroupDataRow(group, viewByInteger);
                dataRows.AddRange(groupDataRows);
            }

            return dataRows;
        }

        private List<GridDataRow> BuildFooter(UserNameViewStatisticsModel grandTotal, bool viewByInteger)
        {
            var dataRow = BuildFooterDataRow(grandTotal, viewByInteger);
            return new List<GridDataRow> { dataRow };
        }

        private GridDataRow BuildFooterDataRow(UserNameViewStatisticsModel statistic, bool viewByInteger)
        {
            var dataRow = gridDataRowBuilderService.BuildBaseDataRow(statistic, viewByInteger);

            if (dataRow != null)
            {
                dataRow.Columns.Insert(0,
                    new Columns { Name = "ReportBy", Value = "Grand Total RM", CellAlignment = HAlignment.Right });
                dataRow.Columns.Insert(1,
                    new Columns { Name = "NoOfPlayers", Value = statistic.NoOfPlayers, CellAlignment = HAlignment.Right });
            }

            return dataRow;
        }
    }
}